/**
 * Switches between peer views of one subject (`design/components/tabs.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tabs.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/tabs'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  Spread,
  agentMember,
  classes,
  derived,
  elementRef,
  getters,
  mergeParts,
  mountEffect,
  normalizeProps,
  provideOwner,
  revealInline,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  watchEffect,
  type Each,
  type IconProps,
  type IconRole,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/overlays/tabs.module.css'
import { Badge, type BadgeProps } from '../structure/Badge'

export type TabsOrientation = NonNullable<TabsProps['orientation']>

export interface TabDescriptor {
  value: string
  label: string
  icon?: IconRole
  count?: number
  disabled?: boolean
}

/** Switches between peer views of one subject: the inputs it takes, by the React member's prop names. */
export interface TabsProps {
  defaultValue?: string
  /**
   * Keeps inactive panels mounted and `hidden` (Radix `forceMount`), so a form being edited or
   * an embedded player survives a tab switch. The default unmounts them, so the common case does
   * not pay to mount everything.
   */
  keepMounted?: boolean
  /**
   * Vertical is the same component on its side, with the rule down the start edge instead of
   * along the bottom. Use it when labels are long enough that a horizontal strip would wrap,
   * because wrapped tabs no longer read as peers.
   */
  orientation?: 'horizontal' | 'vertical'
  tabs: TabDescriptor[]
  value?: string
}

/** What Tabs hands its compound parts. */
export interface TabsOwner {
  readonly api: zag.Api
  readonly keepMounted: Exclude<TabsProps['keepMounted'], undefined>
}

/** Switches between peer views of one subject. */
@Component({
  selector: 'pm-tabs',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS, provideOwner('Tabs')],
  imports: [Ref, SlotOutlet, SlotTemplate, Spread, Badge, Icon],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<!-- root -->
<div
[pmSpread]="e1()"
><!-- list -->
<div
[pmSpread]="e2()"
[pmRef]="list"
>@for (tab of e3(); track e4(tab)) {<!-- tab -->
<button
[pmSpread]="e5(tab)"
>@if (e6(tab)) {<span
[attr.class]="e7(tab)"
><pm-icon
[name]="e8(tab)"
size="sm"
></pm-icon></span>}
<span>{{ e9(tab) }}</span>
@if (e10(tab)) {<span
[attr.class]="e11(tab)"
><pm-badge
[tone]="e12(tab)"
>{{ e13(tab) }}</pm-badge></span>}</button>}
<!-- indicator -->
<div
[pmSpread]="e14()"
></div></div>
<ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></div>`,
})
export class Tabs {
  readonly defaultValue = input<TabsProps['defaultValue']>(undefined)
  /**
   * Keeps inactive panels mounted and `hidden` (Radix `forceMount`), so a form being edited or
   * an embedded player survives a tab switch. The default unmounts them, so the common case does
   * not pay to mount everything.
   */
  readonly keepMounted = input<
    Exclude<TabsProps['keepMounted'], undefined>,
    TabsProps['keepMounted']
  >(false, {
    transform: (value: TabsProps['keepMounted']) => (value === undefined ? false : value),
  })
  /**
   * Vertical is the same component on its side, with the rule down the start edge instead of
   * along the bottom. Use it when labels are long enough that a horizontal strip would wrap,
   * because wrapped tabs no longer read as peers.
   */
  readonly orientation = input<
    Exclude<TabsProps['orientation'], undefined>,
    TabsProps['orientation']
  >('horizontal', {
    transform: (value: TabsProps['orientation']) => (value === undefined ? 'horizontal' : value),
  })
  readonly tabs = input.required<TabsProps['tabs']>()
  readonly value = input<TabsProps['value']>(undefined)
  readonly onChange = output<string>({ alias: 'change' })
  protected readonly $ = useMember({
    events: ['change'],
    props: {
      defaultValue: () => this.defaultValue(),
      keepMounted: () => this.keepMounted(),
      orientation: () => this.orientation(),
      tabs: () => this.tabs(),
      value: () => this.value(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly list = elementRef<HTMLElement>()
  protected readonly documentDirection = useDirection()
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          value: this.$p.value,
          defaultValue: this.$p.defaultValue ?? this.$p.tabs[0]?.value,
          orientation: this.$p.orientation,
          onValueChange: (details) => {
            this.$.emit(this.onChange, 'onChange', details.value)
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  private release1: (() => void) | undefined
  private release3: (() => void) | undefined

  constructor() {
    this.$.owner = getters<TabsOwner>({
      api: () => this.api.value,
      keepMounted: () => this.$p.keepMounted,
    })
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
    watchEffect(
      () => this.api.value.value,
      () => this.effect2(),
      false,
    )
    inject(DestroyRef).onDestroy(() => this.release3?.())
    mountEffect(() => this.effect3())
  }

  protected e1() {
    return mergeParts(this.api.value.getRootProps(), { class: styles.root, 'data-member': 'tabs' })
  }

  protected e2() {
    return mergeParts(this.api.value.getListProps(), {
      class: styles.list,
      'data-tabs-part': 'list',
    })
  }

  e3() {
    return this.$p.tabs
  }

  protected e4(tab: Each<ReturnType<Tabs['e3']>>) {
    return tab.value
  }

  protected e5(tab: Each<ReturnType<Tabs['e3']>>) {
    return mergeParts(
      this.api.value.getTriggerProps({ value: tab.value, disabled: tab.disabled }),
      {
        class: styles.trigger,
        'data-tabs-part': 'tab',
        'data-state': this.api.value.value === tab.value ? 'active' : 'inactive',
        'data-disabled': tab.disabled ? '' : undefined,
      },
    )
  }

  protected e6(tab: Each<ReturnType<Tabs['e3']>>) {
    return tab.icon !== undefined
  }

  protected e7(tab: Each<ReturnType<Tabs['e3']>>) {
    if (!(tab.icon !== undefined)) return undefined as never
    return styles.glyph
  }

  protected e8(tab: Each<ReturnType<Tabs['e3']>>): IconProps['name'] {
    if (!(tab.icon !== undefined)) return undefined as never
    return tab.icon
  }

  protected e9(tab: Each<ReturnType<Tabs['e3']>>) {
    return tab.label
  }

  protected e10(tab: Each<ReturnType<Tabs['e3']>>) {
    return tab.count !== undefined
  }

  protected e11(tab: Each<ReturnType<Tabs['e3']>>) {
    if (!(tab.count !== undefined)) return undefined as never
    return styles.count
  }

  protected e12(tab: Each<ReturnType<Tabs['e3']>>): BadgeProps['tone'] {
    if (!(tab.count !== undefined)) return undefined as never
    return this.api.value.value === tab.value ? 'accent' : 'neutral'
  }

  protected e13(tab: Each<ReturnType<Tabs['e3']>>) {
    if (!(tab.count !== undefined)) return undefined as never
    return String(tab.count)
  }

  protected e14() {
    return mergeParts(this.api.value.getIndicatorProps(), {
      class: classes(styles.indicator, styles.slide),
      style: {
        'inline-size':
          this.$p.orientation === 'vertical'
            ? undefined
            : Object(this.api.value.getIndicatorProps().style)['--width'],
        'block-size':
          this.$p.orientation === 'vertical'
            ? Object(this.api.value.getIndicatorProps().style)['--height']
            : undefined,
      },
    })
  }

  private effect1(): void {
    this.release1?.()
    const run = () => {
      revealInline(this.list.value, this.list.value?.querySelector('[data-state="active"]'), true)
    }
    const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
    for (const element of [this.list.value]) if (element) resize?.observe(element)
    this.release1 = () => {
      resize?.disconnect()
    }
    run()
  }

  private effect2(): void {
    revealInline(this.list.value, this.list.value?.querySelector('[data-state="active"]'))
  }

  private effect3(): void {
    this.release3?.()
    const ran = agentMember({
      member: 'Tabs',
      element: () => this.list.value,
      state: () => ({
        value: this.api.value.value ?? null,
        tabs: this.$p.tabs.map((tab) => ({
          id: tab.value,
          label: tab.label,
          ...(tab.disabled === true ? { disabled: true } : {}),
        })),
      }),
      actions: {
        choose: {
          argument: 'id',
          run: (value) => value === this.api.value.value || this.api.value.setValue(value),
        },
      },
    })
    this.release3 = () => {
      ran()
    }
  }
}
